async function reconnect(client, savedSession) {
  const stillValid = savedSession && !savedSession.expired;
  if (stillValid) {
    return resumeSession(client, savedSession);
  }
  return startNewSession(client);
}

function onReconnect(client, server) {
  const capabilities = server.getPersistedCapabilities(client.id);
  const subscriptions = server.getPersistedSubscriptions(client.id);
  client.restore({ capabilities, subscriptions, history: client.loadCheckpoint() });
}

function shouldResume(savedSession, maxAgeMs) {
  if (!savedSession) return false;
  const age = Date.now() - savedSession.lastSeenAt;
  return age < maxAgeMs;
}
